// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 msgValue) public {
        vm.assume(msgValue > 0);

        uint256 pastBlockTimeBefore = c.pastBlockTime();

        (bool success,) = address(c).call{value: msgValue}("");

        uint256 pastBlockTimeAfter = c.pastBlockTime();

        if (msgValue == 10 ether) {
            assertTrue(success && pastBlockTimeAfter > pastBlockTimeBefore);
        } else {
            assertTrue(!success && pastBlockTimeAfter == pastBlockTimeBefore);
        }
    }
}

